-- State transitions declared for LDAPDirectory (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.ldap_directories_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'error'), ('active', 'inactive'), ('draft', 'active'), ('draft', 'error'), ('error', 'active'), ('error', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: ldap_directories.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS ldap_directories_status_transition_check ON sapiens.ldap_directories;
CREATE TRIGGER ldap_directories_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.ldap_directories
    FOR EACH ROW EXECUTE FUNCTION sapiens.ldap_directories_status_transition_check();
